INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-saft-introduced', id, '2008-01-01', 1, NULL FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-introduced', 'en', 'SAF-T digital audit file introduced', 'The foundation of Portugal''s modern fiscalization system, well before any e-invoicing mandate existed — this file format underpins the reporting obligations that came later.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-certified-software', id, '2010-06-01', 1, NULL FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-certified-software', 'en', 'Certified invoicing software becomes mandatory', 'The true start of Portugal''s modern fiscal system: all invoices, regardless of format, must be issued using software certified by the Autoridade Tributária (AT).', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-lei-111b', id, '2017-01-01', 1, NULL FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-111b', 'en', 'Lei n.º 111-B/2017 transposes the EU public-procurement e-invoicing directive', 'Establishes the legal basis for Portugal''s B2G e-invoicing regime, implementing EU Directive 2014/55/EU into national law.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-public-bodies-receive', id, '2019-04-18', 1, 'https://www.portaldasfinancas.gov.pt/pt/menu.action?pai=5075' FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-public-bodies-receive', 'en', 'Public bodies must receive and process e-invoices', 'Public administration entities become obliged to receive and process structured e-invoices, via the centralised eSPap-operated platform or a designated service provider.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-b2g-large', id, '2021-01-01', 0, 'https://www.portaldasfinancas.gov.pt/pt/menu.action?pai=5075' FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-large', 'en', 'B2G e-invoicing mandatory for large companies (in force since Jan 2021)', 'Large companies supplying public administration bodies must issue structured e-invoices in the national CIUS-PT format (a Portuguese implementation of EN 16931, via UBL 2.1 or CEFACT CII), transmitted through the eSPap-operated FE-AP platform or another approved channel. Portugal has no general B2B or B2C e-invoicing mandate — this requirement applies specifically to public-sector supply.', '["Confirm your invoicing system can generate valid CIUS-PT structured XML, not just a PDF representation", "Connect to FE-AP or an approved alternative channel for transmitting invoices to public bodies"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-qr-code', id, '2022-01-01', 1, NULL FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qr-code', 'en', 'QR code becomes mandatory on all invoices', 'Every invoice — paper or electronic, B2G or otherwise — must carry a QR code enabling validation, alongside the existing ATCUD unique document code requirement.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-lei-82-2023', id, '2023-01-01', 1, NULL FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-82-2023', 'en', 'Lei n.º 82/2023 amends the B2G framework', 'Refines and extends the legal basis established by Lei n.º 111-B/2017.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-b2g-sme', id, '2026-01-01', 0, 'https://www.portaldasfinancas.gov.pt/pt/menu.action?pai=5075' FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-sme', 'en', 'B2G mandate extends to small, medium, and micro-enterprises', 'The structured CIUS-PT issuance requirement for public-sector suppliers, previously applying only to large companies, now extends to small, medium, and micro-enterprises. Separately, regardless of company size or whether B2G applies, all invoices — paper or electronic — must already be issued using AT-certified software and carry an ATCUD code, a QR code, and a hash chain for authenticity.', '["If you supply any Portuguese public-sector body and don''t yet issue structured CIUS-PT invoices, this is now a live compliance gap, not a future one", "Independently of B2G status, confirm your invoicing software is on the AT-certified list \u2014 using uncertified software invalidates an invoice regardless of its content"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-qes', id, '2027-01-01', 0, 'https://www.portaldasfinancas.gov.pt/pt/menu.action?pai=5075' FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qes', 'en', 'Qualified Electronic Signature (QES) required for PDF invoices', 'PDF invoices in B2B and B2C transactions will require a Qualified Electronic Signature from an EU-listed trust service provider to remain legally valid — deferred from an original 2026 date via the 2026 State Budget. Until 31 December 2026, PDF invoices issued by certified software with ATCUD and a QR code remain valid without a QES.', '["Identify an EU-listed qualified trust service provider for QES well before the 2027 deadline \u2014 this is a procurement step, not a software setting", "Don''t assume compliance with the existing ATCUD/QR/certified-software requirements covers this \u2014 QES is a genuinely new, additional layer specifically for PDF invoices"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'pt-saft-full', id, '2028-01-01', 1, 'https://www.portaldasfinancas.gov.pt/pt/menu.action?pai=5075' FROM countries WHERE name_en = 'Portugal';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-full', 'en', 'Full accounting SAF-T file becomes mandatory', 'The first mandatory full annual accounting SAF-T submission, covering 2027-year transactions, becomes due — itself deferred from an earlier 2026 timeline via the same State Budget process.', '[]');
